  let outset = mat3x3f(vec3f(1.1271006, -0.14132976, -0.14132976), vec3f(-0.11060664, 1.1578237, -0.11060664), vec3f(-0.016493939, -0.016493939, 1.2519364)) * lume_agx_contrast(encoded);
